INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q01','9','geografie-fizica','published',0,201,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q01','ro','Un râu curge întâi printr-un masiv de calcar dur, apoi printr-un podiș de argile moi. Unde va fi valea mai îngustă (chei) și unde mai largă?','["Îngustă în calcarul dur (chei) și largă în argilele moi.","Valea e la fel de largă în ambele, fiindcă e același râu.","Îngustă în argile și largă în calcar.","Râul nu poate traversa roci dure."]','Roca dură rezistă la eroziunea laterală, așa că râul se adâncește și lasă versanți abrupți (chei, canioane); în roca moale, malurile se surpă ușor și valea se lărgește.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q02','9','geografie-fizica','published',1,202,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q02','ro','De ce râurile fac meandre în câmpie, dar sapă văi înguste și adânci la munte?','["La munte apa este mai multă.","La munte panta mare favorizează eroziunea în adâncime, iar în câmpie panta mică favorizează eroziunea laterală și meandrele.","În câmpie roca este mereu mai dură.","Meandrele apar doar unde plouă mult."]','Panta hotărăște tipul de eroziune: pe pante mari apa taie în adâncime (văi înguste); pe pante mici energia se consumă lateral, iar râul șerpuiește (meandre).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q03','9','geografie-fizica','published',2,203,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q03','ro','Două fluvii se varsă în mare: unul formează o deltă, celălalt un estuar larg. Ce explică diferența?','["Estuarele apar doar la fluviile mici.","Delta apare unde mareele și curenții spală sedimentele; estuarul unde ele lipsesc.","Delta apare unde fluviul aduce multe aluviuni și marea le lasă pe loc; estuarul unde mareele și curenții împrăștie aluviunile.","Nu există nicio diferență reală."]','Delta se construiește când aportul de aluviuni depășește capacitatea mării de a le îndepărta; dacă mareele și curenții sunt puternici, ei împrăștie sedimentele și rămâne un estuar deschis.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q04','9','geografie-fizica','published',3,204,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q04','ro','Terasele fluviale (pod și frunte) etajate deasupra luncii arată că râul...','["a curs mereu la același nivel.","și-a lărgit doar albia.","a secat complet.","s-a adâncit în timp, lăsând vechile lunci suspendate ca terase."]','Fiecare terasă este o veche luncă, rămasă mai sus după ce râul s-a adâncit din nou. Etajarea teraselor este o scară a adâncirii succesive a văii.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q05','9','geografie-fizica','published',0,205,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q05','ro','Pe un versant fără vegetație apar, în timp, întâi rigole, apoi ravene, apoi ogașe. Ce arată această succesiune?','["Adâncirea și permanentizarea treptată a șanțurilor săpate de șiroire.","Că versantul se aplatizează.","Că apa curge tot mai puțin.","Că se depune sol nou."]','Rigolele sunt mici și trecătoare; prin repetarea ploilor se adâncesc în ravene, apoi în ogașe adânci și permanente. Este o intensificare a eroziunii în adâncime pe versant.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q06','9','geografie-fizica','published',1,206,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q06','ro','De ce ravenele și alunecările apar mult mai des pe versanții despăduriți?','["Fiindcă pădurea încălzește solul.","Fiindcă rădăcinile și covorul vegetal fixează solul și rețin apa; fără ele, apa spală și urnește ușor materialul.","Fiindcă acolo plouă mai mult.","Fiindcă roca devine mai dură."]','Vegetația protejează versantul: rădăcinile leagă solul, iar frunzișul frânge ploaia. Despădurirea lasă solul descoperit, ușor de spălat (ravene) și de urnit (alunecări).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q07','9','geografie-fizica','published',2,207,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q07','ro','La ieșirea unui torent din munte, la baza pantei, se formează un con de dejecție. De ce tocmai acolo?','["Fiindcă acolo roca este mai moale.","Fiindcă acolo plouă mai mult.","Fiindcă acolo panta scade brusc, apa își pierde viteza și depune materialul cărat.","Fiindcă apa sapă mai adânc."]','Cât timp panta este mare, apa are energie și transportă. Când ajunge la câmpie și panta scade, viteza scade, iar aluviunile se depun în evantai — conul de dejecție.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q08','9','geografie-fizica','published',3,208,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q08','ro','De ce alunecările de teren se produc mai ales pe versanți argiloși și mai ales după ploi lungi?','["Fiindcă argila uscată este foarte tare.","Fiindcă ploaia dizolvă argila.","Fiindcă argila îngheață.","Fiindcă argila îmbibată cu apă devine alunecoasă și grea, iar gravitația urnește masa pe pantă."]','Argila nu lasă apa să treacă; îmbibată, se transformă într-un strat alunecos pe care masa de deasupra, îngreunată de apă, alunecă la vale sub acțiunea gravitației.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q09','9','geografie-fizica','published',0,209,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q09','ro','Crovurile, hornurile și tunelurile de sufoziune apar aproape numai în loess. De ce nu și în granit?','["Fiindcă loessul este o rocă afânată și poroasă, prin care apa se infiltrează, spală și tasează materialul; granitul este compact.","Fiindcă granitul este mai vechi.","Fiindcă în loess plouă mai mult.","Fiindcă loessul este mai colorat."]','Loessul este o pulbere afânată, ușor de străbătut de apă; aceasta îl spală pe dedesubt (sufoziune) și îl îndeasă (tasare), formând crovuri și tuneluri. Granitul, compact, nu permite astfel de procese.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q10','9','geografie-fizica','published',1,210,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q10','ro','De ce văile glaciare au profil în forma literei U, iar cele fluviale în forma literei V?','["Fiindcă râul este mai puternic decât ghețarul.","Fiindcă ghețarul, lat și gros, erodează toată lățimea văii, pe când râul taie doar la fund, îngust.","Fiindcă gheața este mai caldă.","Fiindcă văile glaciare sunt mai noi."]','Râul erodează mai ales pe firul apei, dând un V îngust. Ghețarul, care umple toată valea, râcâie și fundul, și pereții, lărgind-o în U.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q11','9','geografie-fizica','published',2,211,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q11','ro','Un fiord este, de fapt...','["o vale fluvială inundată de ploi.","un golf săpat de valuri.","o vale glaciară adâncă, invadată ulterior de apa mării.","un crater vulcanic."]','Ghețarii au săpat văi adânci în munți; după topirea gheții, marea a pătruns în ele. Așa au apărut fiordurile — de aceea sunt lungi, adânci și cu pereți abrupți.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q12','9','geografie-fizica','published',3,212,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q12','ro','Un geograf găsește, într-o vale fără ghețari azi, valuri de pietriș și bolovani amestecați, numite morene. Ce deduce?','["Că a fost o erupție vulcanică.","Că este o plajă veche.","Că apa a depus nisip fin.","Că valea a fost cândva ocupată de un ghețar, care a cărat și a depus acel material."]','Morenele sunt grămezi de material cărat și lăsat de ghețari, nesortat (de la praf la bolovani). Prezența lor arată că, în trecut, gheața a modelat acea vale.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q13','9','geografie-fizica','published',0,213,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q13','ro','Pe o stâncă se văd zgârieturi paralele (striuri glaciare). La ce folosesc geografilor?','["Arată direcția în care s-a deplasat ghețarul.","Arată vârsta rocii.","Arată temperatura aerului.","Arată adâncimea mării."]','Pietrele prinse la baza ghețarului zgârie roca pe direcția de curgere a gheții. Striurile păstrează, ca niște săgeți, direcția în care s-a mișcat cândva ghețarul.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q14','9','geografie-fizica','published',1,214,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q14','ro','Grohotișurile (mări de pietre) de sub crestele înalte se formează mai ales prin gelifracție. De ce sunt tipice zonelor reci și înalte?','["Fiindcă acolo bate mereu vântul cald.","Fiindcă acolo apa din crăpături îngheață și se dezgheață des, iar gheața, dilatându-se, sfărâmă roca.","Fiindcă roca este mai moale la altitudine.","Fiindcă plouă torențial."]','Gelifracția cere treceri repetate prin 0 grade. La altitudine mare și la latitudini reci, înghețul-dezghețul se produce des; apa din crăpături îngheață, se dilată și desface roca în blocuri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q15','9','geografie-fizica','published',2,215,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q15','ro','De ce vântul este agentul modelator dominant în deșerturi, dar aproape neînsemnat într-o pădure?','["Fiindcă în deșert vântul este mai rece.","Fiindcă în pădure nu bate niciodată vântul.","Fiindcă în deșert lipsesc vegetația și umezeala, iar nisipul uscat și liber poate fi ridicat și purtat ușor de vânt.","Fiindcă nisipul este mai greu decât frunzele."]','Vântul lucrează doar cu material uscat și liber. În deșert, fără plante și fără apă care să lege particulele, nisipul este la cheremul vântului; în pădure, vegetația și umezeala îl fixează.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q16','9','geografie-fizica','published',3,216,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q16','ro','Ciupercile eoliene (roci cu picior subțire și pălărie lată) se explică prin faptul că...','["ploaia sapă partea de sus.","roca crește precum o ciupercă.","gheața taie baza.","vântul erodează mai puternic aproape de sol, unde cară cel mai mult nisip."]','Vântul poartă nisipul mai ales în primii metri de la sol. Coraziunea (izbirea cu nisip) este mai intensă la bază, care se subțiază, în timp ce partea de sus rămâne mai groasă — de unde forma de ciupercă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q17','9','geografie-fizica','published',0,217,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q17','ro','Barcanele (dune în formă de semilună) au un versant lin și unul abrupt. Ce se poate citi din forma lor?','["Direcția vântului dominant (vine dinspre versantul lin spre cel abrupt).","Adâncimea nisipului.","Cantitatea de ploaie.","Vârsta deșertului."]','Vântul urcă nisipul pe panta lină și îl lasă să cadă pe partea adăpostită, abruptă. Așa, barcana arată mereu încotro bate vântul — și chiar se deplasează în acel sens.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q18','9','geografie-fizica','published',1,218,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q18','ro','Într-o câmpie deșertică netedă se înalță brusc un munte-martor izolat (inselberg). Cum a apărut?','["A fost adus de vânt.","Este o rămășiță dintr-un relief mai înalt, dintr-o rocă mai dură, care a rezistat eroziunii ce a nivelat restul.","A fost ridicat de un vulcan recent.","Este o dună împietrită."]','Eroziunea îndelungată a coborât câmpia (pediplenă), dar un petic de rocă mai rezistentă a rămas pe loc, ca un martor. Inselbergul arată unde roca a fost mai tare decât în jur.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q19','9','geografie-fizica','published',2,219,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q19','ro','De ce unele deșerturi sunt pietroase (hamada/reg), iar altele acoperite de nisip (erg)?','["Fiindcă în hamada nu a plouat niciodată.","Fiindcă pietrele cresc din nisip.","Fiindcă vântul (deflația) ridică și duce particulele fine, lăsând pietrele pe loc și adunând nisipul în altă parte.","Fiindcă ergul este mai vechi."]','Deflația sortează deșertul: vântul spulberă praful și nisipul fin dintr-un loc (rămâne hamada pietroasă) și le îngrămădește în altul, unde se formează câmpuri de dune (erg).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q20','9','geografie-fizica','published',3,220,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q20','ro','Sub lovitura valurilor, o faleză (țărm înalt și abrupt) în timp...','["înaintează în mare.","rămâne neschimbată.","se transformă în deltă.","se retrage spre uscat, lăsând în față o platformă de abraziune."]','Valurile sapă la baza falezei (abraziune); partea de sus, subminată, se prăbușește, iar țărmul se retrage. În urma retragerii rămâne o suprafață netedă tăiată în rocă — platforma de abraziune.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q21','9','geografie-fizica','published',0,221,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q21','ro','Țărmul cu fiorduri, cel cu rias și cel dalmatic sunt toate țărmuri înalte, dantelate. Ce au în comun la origine?','["Toate sunt foste văi (glaciare sau fluviale) și forme de relief invadate de apa mării.","Toate au fost create de valuri.","Toate sunt vulcanice.","Toate sunt formate din nisip."]','Marea a inundat un relief preexistent: văi glaciare (fiord), văi fluviale perpendiculare pe țărm (rias) sau culmi și văi paralele cu țărmul (dalmatic). Adâncirea în uscat le dă aspectul crestat.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q22','9','geografie-fizica','published',1,222,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q22','ro','Un liman sau o lagună apar când...','["un râu sapă în adâncime.","un cordon de nisip (perisip) închide un golf sau o gură de vale, izolând un lac lângă țărm.","valurile taie o faleză.","gheața topește uscatul."]','Curenții și valurile construiesc un cordon de nisip care baricadează o intrândă. Apa rămasă în spate formează un liman (la gura unei văi) sau o lagună (în lungul țărmului).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q23','9','geografie-fizica','published',2,223,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q23','ro','Peșterile, dolinele și lapiezurile (relief carstic) apar în calcar și în sare, dar nu în granit. De ce?','["Fiindcă granitul este prea moale.","Fiindcă în calcar nu plouă.","Fiindcă doar calcarul și sarea se dizolvă în apă, iar carstul se formează prin dizolvare.","Fiindcă granitul este mai colorat."]','Relieful carstic se naște prin dizolvarea rocii de către apă. Calcarul și sarea sunt solubile, deci pot fi mâncate de apă; granitul, insolubil, nu poate forma astfel de goluri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q24','9','geografie-fizica','published',3,224,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q24','ro','Într-o peșteră, stalactitele cresc din tavan în jos, iar stalagmitele de pe podea în sus. Cum se formează?','["Prin dizolvarea rapidă a tavanului.","Prin înghețarea apei.","Prin acțiunea vântului.","Prin depunerea (precipitarea) calcarului din picăturile de apă care se preling și pică."]','Apa încărcată cu calcar dizolvat se prelinge; când picură, o parte din calcar se depune. Sus, la vârful picăturii, crește stalactita; jos, unde cade, crește stalagmita — proces invers dizolvării.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q25','9','geografie-fizica','published',0,225,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q25','ro','Aceeași rocă (granitul) dă blocuri rotunjite (căpățâni de zahăr) în climatul cald și umed, dar creste ascuțite în climatul rece. De ce?','["Fiindcă în climatul cald-umed predomină alterarea chimică (rotunjește), iar în climatul rece dezagregarea prin îngheț (colțuroasă).","Fiindcă granitul este diferit în fiecare loc.","Fiindcă în climat rece granitul este mai moale.","Fiindcă vântul rotunjește roca la tropice."]','Clima hotărăște procesul: la cald și umed alterarea chimică macină colțurile și rotunjește blocurile; la rece gelifracția sparge roca în forme ascuțite. Roca este aceeași, dar agentul diferă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q26','9','geografie-fizica','published',1,226,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q26','ro','Babele și Sfinxul (Bucegi), sculptate în conglomerate, s-au format mai ales prin...','["dizolvarea rocii, ca la calcar.","acțiunea combinată a înghețului-dezghețului și a vântului, care roade inegal roca.","depunerea de aluviuni.","erupții vulcanice."]','Conglomeratul are părți mai tari și mai moi. Înghețul-dezghețul și vântul cu nisip rod mai repede porțiunile moi, lăsând forme bizare (babe, sfincși). Este eroziune diferențiată, nu dizolvare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q27','9','geografie-fizica','published',2,227,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q27','ro','Coloanele de bazalt (de exemplu la Detunata) au forma unor stâlpi regulați fiindcă...','["au fost tăiate de oameni.","apa le-a șlefuit.","lava s-a răcit și s-a contractat, crăpând în prisme regulate.","au crescut precum niște cristale de sare."]','La răcire, lava bazaltică se contractă și crapă în rețea, formând prisme (de obicei hexagonale). Coloanele de bazalt sunt amprenta acestei contracții la solidificare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q28','9','geografie-fizica','published',3,228,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q28','ro','O cuestă are o frunte abruptă și o spinare domoală. Ce hotărăște această asimetrie?','["Vântul dominant.","Cantitatea de ploaie.","Prezența unui râu.","Înclinarea stratelor de roci: spinarea urmează panta stratului, iar fruntea taie stratele."]','În structura monoclinală, stratele sunt înclinate. Pe o parte relieful urmează panta stratului dur (spinarea, domoală), pe cealaltă eroziunea retează capetele stratelor (frunte abruptă).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q29','9','geografie-fizica','published',0,229,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q29','ro','Inversiunea de relief înseamnă că, în timp, pe sinclinal apare o culme, iar pe anticlinal o vale. Cum se explică?','["Anticlinalul, boltit și fisurat, este erodat mai ușor și devine vale, iar sinclinalul, mai îndesat, rezistă și rămâne culme.","Rocile se mută singure.","Vântul ridică sinclinalul.","Apa umple anticlinalul."]','Bolta anticlinalului este întinsă și crăpată, deci mai ușor de erodat — se scobește în vale. Sinclinalul are rocile îndesate, rezistă mai bine și ajunge, paradoxal, culme. Așa apare inversiunea de relief.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q30','9','geografie-fizica','published',1,230,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q30','ro','Horsturile și grabenele sunt forme legate de structura...','["tabulară.","faliată (blocuri ridicate și blocuri coborâte între falii).","cutată.","monoclinală."]','Când scoarța se rupe în falii, unele blocuri urcă (horst), altele coboară (graben). Relieful rezultat oglindește direct structura faliată a rocilor.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q31','9','geografie-fizica','published',2,231,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q31','ro','Atolii de corali (relief biogen) se întâlnesc doar în mările calde, tropicale, puțin adânci. De ce?','["Fiindcă acolo apa este dulce.","Fiindcă valurile sunt mai mari acolo.","Fiindcă coralii, viețuitoarele care îi construiesc, trăiesc numai în ape calde, limpezi și puțin adânci.","Fiindcă nisipul este alb."]','Atolul este clădit de colonii de corali; aceștia au nevoie de apă caldă, curată și luminoasă (deci puțin adâncă). De aceea relieful coraligen apare doar în mările tropicale.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q32','9','geografie-fizica','published',3,232,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q32','ro','Ce au în comun mușuroaiele de termite, recifele de corali și scoarțele de alterare de sub o pădure?','["Sunt create de vânt.","Sunt forme vulcanice.","Sunt depuse de râuri.","Sunt forme de relief la care agentul principal sunt viețuitoarele (relief biogen)."]','În toate, formele sunt rezultatul activității organismelor — animale (termite, corali) sau plante (alterarea prin rădăcini). Agentul modelator este viul, de unde numele de relief biogen.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q33','9','geografie-fizica','published',0,233,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q33','ro','Carierele, haldele și barajele sunt considerate relief antropic pentru că...','["sunt forme de relief create direct de om, prin exploatare și construcție.","au apărut singure în timp.","sunt modelate de ghețari.","sunt forme carstice."]','Relieful antropic este cel făcut de om: sapă (cariere), îngrămădește (halde) sau ridică (baraje, diguri). Omul devine astfel un agent modelator al scoarței.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q34','9','geografie-fizica','published',1,234,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q34','ro','În lecție, roca și structura sunt numite factori pasivi, iar apa sau vântul agenți. Care este diferența?','["Roca lucrează, iar apa doar stă.","Agenții acționează activ (sapă, transportă, depun), pe când roca și structura doar hotărăsc ce forme apar, fără a le crea singure.","Nu există nicio diferență.","Factorii pasivi sunt mereu mai importanți."]','Agenții externi (apa, gheața, vântul) fac efectiv modelarea. Roca și structura nu modelează nimic singure, dar aleg ce forme rezultă (dure vs moi, orizontale vs cutate) — de aceea sunt pasive.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q35','9','geografie-fizica','published',2,235,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q35','ro','Apa, ca agent, dă forme foarte diferite: chei în calcar, alunecări în argilă, terase într-o luncă. Ce arată acest lucru?','["Că apa își schimbă natura de la un loc la altul.","Că formele nu au nicio legătură cu apa.","Că același agent produce forme diferite în funcție de rocă, pantă și climă.","Că apa erodează la fel peste tot."]','Rezultatul depinde de condiții: aceeași apă sapă chei în calcar dur, urnește argila îmbibată sau lasă terase în lunca unui râu. Varietatea reliefului vine din combinația agent–rocă–pantă–climă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q36','9','geografie-fizica','published',3,236,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q36','ro','Prin eroziune regresivă, un râu își lungește valea înapoi, spre izvor, și poate ajunge să fure apa unui râu vecin. Cum se numește fenomenul și ce îl produce?','["Meandrare; produsă de pantă mică.","Abraziune; produsă de valuri.","Deflație; produsă de vânt.","Captare; produsă de adâncirea și înaintarea văii spre amonte."]','Eroziunea regresivă mută obârșia văii tot mai spre amonte. Când o vale sparge cumpăna și ajunge la un râu vecin, îi deviază apa — este captarea, cu vale moartă și clisură în urmă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q37','9','geografie-fizica','published',0,237,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q37','ro','Circul glaciar (o adâncitură ca un jilț, la obârșia văii glaciare) marchează locul unde...','["se aduna și se năștea ghețarul, săpând roca prin greutatea și mișcarea gheții.","râul se varsă în mare.","vântul a adunat nisip.","s-a produs o erupție."]','În circ se strângea zăpada care se transforma în gheață; de aici pornea ghețarul. Greutatea și mișcarea gheții au scobit roca, lăsând adâncitura caracteristică de la obârșia văii glaciare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q38','9','geografie-fizica','published',1,238,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q38','ro','Solifluxiunea (curgerea lentă a solului îmbibat pe un versant) este tipică regiunilor periglaciare. De ce apare mai ales acolo?','["Fiindcă acolo este mereu secetă.","Fiindcă solul dezghețat la suprafață, îmbibat cu apă, alunecă peste stratul înghețat de dedesubt.","Fiindcă vântul împinge solul.","Fiindcă roca este vulcanică."]','Vara, doar stratul de la suprafață se dezgheață; îmbibat cu apă și sprijinit pe permafrostul de dedesubt, el curge lent la vale. De aceea solifluxiunea este caracteristică zonelor periglaciare.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q39','9','geografie-fizica','published',2,239,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q39','ro','În deșert, rocile se sparg adesea singure, deși aproape nu plouă. Ce proces explică asta?','["Dizolvarea.","Abraziunea marină.","Dezagregarea termică: încălzirea puternică ziua și răcirea noaptea dilată și contractă roca până o fisurează.","Solifluxiunea."]','Contrastele mari de temperatură zi–noapte fac roca să se dilate și să se contracte repetat. Tensiunile o fisurează și o sfărâmă, chiar fără apă — este dezagregarea (meteorizația) termică.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('rm-q40','9','geografie-fizica','published',3,240,1783800000000,1783800000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('rm-q40','ro','De ce spunem că relieful minor este sculptat, iar relieful major este construit?','["Fiindcă relieful minor este mai frumos.","Fiindcă relieful minor este mai vechi.","Fiindcă ambele sunt create de vânt.","Fiindcă relieful major este ridicat de forțele interne (tectonice), iar peste el agenții externi doar dăltuiesc forme mai mici (relieful minor)."]','Forțele interne înalță marile unități (munți, podișuri, câmpii) — construiesc. Apoi agenții externi le atacă și le detaliază, săpând văi, peșteri, faleze — sculptează relieful minor peste cel major.');
